#include <assert.h>
#include <v8.h>

using namespace v8;

// Placeholder for error codes
typedef enum {
  DOMExceptionGeneralError,
  DOMExceptionTypeError,
  DOMExceptionRangeError,
  DOMExceptionSyntaxError,
  DOMExceptionReferenceError
} DOMExceptionCode;

Local<Value> createDOMException(Local<Context> context, DOMExceptionCode code, const char* message) {
  assert(!context.IsEmpty());
  Isolate* isolate = context->GetIsolate();
  Local<Value> exception;

  switch (code) {
    case DOMExceptionGeneralError:
      exception = Exception::Error(String::NewFromOneByte(isolate, (const uint8_t*)message));
      break;
    case DOMExceptionTypeError:
      exception = Exception::TypeError(String::NewFromOneByte(isolate, (const uint8_t*)message));
      break;
    case DOMExceptionRangeError:
      exception = Exception::RangeError(String::NewFromOneByte(isolate, (const uint8_t*)message));
      break;
    case DOMExceptionSyntaxError:
      exception = Exception::SyntaxError(String::NewFromOneByte(isolate, (const uint8_t*)message));
      break;
    case DOMExceptionReferenceError:
      exception = Exception::ReferenceError(String::NewFromOneByte(isolate, (const uint8_t*)message));
      break;
  }

  Local<Object> exception_obj = exception->ToObject(context).ToLocalChecked();
  Local<String> stack = String::NewFromOneByte(isolate, (const uint8_t*)"stack trace goes here");
  exception_obj->Set(context, String::NewFromOneByte(isolate, (const uint8_t*)"stack"), stack).Check();
  return exception;
}

void throwException(Isolate* isolate, Local<Value> exception) {
  if (!isolate->InContext()) return;
  isolate->ThrowException(exception);
}

void createDOMException(v8::Isolate* isolate, int errorCode, const char* message, v8::Local<v8::Object>& exception) {
  v8::Local<v8::String> errorType;
  v8::Local<v8::Function> constructor;

  switch (errorCode) {
    case 1:
      errorType = v8::String::NewFromUtf8(isolate, "TypeError").ToLocalChecked();
      constructor = v8::Exception::TypeError(errorType);
      break;
    case 2:
      errorType = v8::String::NewFromUtf8(isolate, "RangeError").ToLocalChecked();
      constructor = v8::Exception::RangeError(errorType);
      break;
    case 3:
      errorType = v8::String::NewFromUtf8(isolate, "SyntaxError").ToLocalChecked();
      constructor = v8::Exception::SyntaxError(errorType);
      break;
    case 4:
      errorType = v8::String::NewFromUtf8(isolate, "ReferenceError").ToLocalChecked();
      constructor = v8::Exception::ReferenceError(errorType);
      break;
    default:
      errorType = v8::String::NewFromUtf8(isolate, "Error").ToLocalChecked();
      constructor = v8::Function::New(isolate, v8::FunctionTemplate::New(isolate, v8::EmptyFunctionCallback).GetFunction()).ToLocalChecked();
      break;
  }

  v8::Local<v8::String> msg = v8::String::NewFromUtf8(isolate, message).ToLocalChecked();
  v8::Local<v8::Value> args[] = { msg };

  v8::Local<v8::Function> stackTraceFunction = v8::Function::New(isolate, v8::FunctionTemplate::New(isolate, v8::EmptyFunctionCallback).GetFunction()).ToLocalChecked();
  v8::Local<v8::Object> stackTrace = v8::Object::New(isolate);
  v8::PropertyDescriptor descriptor(v8::String::NewFromUtf8(isolate, "stack").ToLocalChecked(), stackTrace);
  v8::Local<v8::Function> constructorCopy = constructor.As<v8::Function>();

  v8::Local<v8::Object> createdException;
  if (!constructorCopy->NewInstance(isolate->GetCurrentContext(), 1, args).ToLocal(&createdException)) {
    createdException = v8::Object::New(isolate);
  }

  exception = createdException;
}

void throwException(v8::Isolate* isolate, v8::Local<v8::Object> exception) {
  if (!isolate->IsExecutionTerminating()) {
    isolate->ThrowException(exception);
  }
}

