// Static function to throw an exception in the V8 isolate
static void throwException(Isolate* isolate, Local<Value> exception) {
  // Check if execution is already terminating
  if (isolate->IsExecutionTerminating())
    return;

  // Throw the exception
  isolate->ThrowException(exception);
}

// Static function to create a DOMException based on the error code
static Local<Value> createDOMException(Isolate* isolate, int errorCode, const char* message) {
  // Ensure the context is secure (mocked here)
  assert(isolate != nullptr && "Isolate must be valid and not null");

  // Create the appropriate exception type
  Local<Value> exception;
  switch (errorCode) {
    case 1: // General Error
      exception = Exception::Error(String::NewFromUtf8(isolate, message).ToLocalChecked());
      break;
    case 2: // Type Error
      exception = Exception::TypeError(String::NewFromUtf8(isolate, message).ToLocalChecked());
      break;
    case 3: // Range Error
      exception = Exception::RangeError(String::NewFromUtf8(isolate, message).ToLocalChecked());
      break;
    case 4: // Syntax Error
      exception = Exception::SyntaxError(String::NewFromUtf8(isolate, message).ToLocalChecked());
      break;
    case 5: // Reference Error
      exception = Exception::ReferenceError(String::NewFromUtf8(isolate, message).ToLocalChecked());
      break;
    default:
      exception = Exception::Error(String::NewFromUtf8(isolate, "Unknown DOMException type").ToLocalChecked());
      break;
  }

  // Attach stack trace for debugging purposes (example only)
  Local<Object> exceptionObject = exception->ToObject(isolate->GetCurrentContext()).ToLocalChecked();
  exceptionObject->Set(isolate->GetCurrentContext(),
                       String::NewFromUtf8(isolate, "stack").ToLocalChecked(),
                       String::NewFromUtf8(isolate, "MockStackTrace").ToLocalChecked()).Check();

  return exception;
}

