// Function to check if the context is secure before proceeding
static void checkContextSecurity(v8::Local<v8::Context> context) {
  // Placeholder for context security checks
  assert(!context.IsEmpty());
}

// Function to attach a stack trace to the exception object
static void attachStackTrace(v8::Local<v8::Context> context, v8::Local<v8::Object> exception) {
  v8::Isolate* isolate = context->GetIsolate();
  v8::Local<v8::String> stackTrace = v8::StackTrace::CurrentStackTrace(
      isolate, 10, v8::StackTrace::kDetailed);
  exception->Set(context, v8::String::NewFromUtf8(isolate, "stack"), stackTrace).Check();
}

// Function to create a DOM exception based on error code
static v8::Local<v8::Value> createDOMException(v8::Local<v8::Context> context, int errorCode, const char* message) {
  v8::Isolate* isolate = context->GetIsolate();

  checkContextSecurity(context);

  v8::Local<v8::Object> exception;
  switch (errorCode) {
    case 1:
      exception = v8::Exception::Error(isolate, v8::String::NewFromUtf8(isolate, message));
      break;
    case 2:
      exception = v8::Exception::TypeError(isolate, v8::String::NewFromUtf8(isolate, message));
      break;
    case 3:
      exception = v8::Exception::RangeError(isolate, v8::String::NewFromUtf8(isolate, message));
      break;
    case 4:
      exception = v8::Exception::SyntaxError(isolate, v8::String::NewFromUtf8(isolate, message));
      break;
    case 5:
      exception = v8::Exception::ReferenceError(isolate, v8::String::NewFromUtf8(isolate, message));
      break;
    default:
      exception = v8::Exception::Error(isolate, v8::String::NewFromUtf8(isolate, message));
      break;
  }

  attachStackTrace(context, exception);
  return exception;
}

// Function to throw the exception in the V8 isolate
static void throwException(v8::Local<v8::Context> context, v8::Local<v8::Value> exception) {
  v8::Isolate* isolate = context->GetIsolate();
  if (!isolate->InContext() || isolate->IsExecutionTerminating()) {
    return;
  }

  isolate->ThrowException(exception);
}

#include <v8.h>

static v8::Local<v8::Value> createDOMException(int errorCode, const char* message) {
  v8::Local<v8::ObjectTemplate> error_template = v8::ObjectTemplate::New();
  v8::Local<v8::Object> exception = error_template->NewInstance(v8::Isolate::GetCurrent()->GetCurrentContext()).ToLocalChecked();
  exception->Set(v8::Isolate::GetCurrent()->GetCurrentContext(),
                 v8::String::NewFromOneByte(v8::Isolate::GetCurrent(), (const uint8_t*)"code", v8::NewStringType::kNormal).ToLocalChecked(),
                 v8::Integer::New(v8::Isolate::GetCurrent(), errorCode)).Check();
  exception->Set(v8::Isolate::GetCurrent()->GetCurrentContext(),
                 v8::String::NewFromOneByte(v8::Isolate::GetCurrent(), (const uint8_t*)"message", v8::NewStringType::kNormal).ToLocalChecked(),
                 v8::String::NewFromOneByte(v8::Isolate::GetCurrent(), (const uint8_t*)message, v8::NewStringType::kNormal).ToLocalChecked()).Check();

  v8::Local<v8::StackTrace> stack_trace = v8::StackTrace::CurrentStackTrace(v8::Isolate::GetCurrent(), 10);
  if (!stack_trace->IsEmpty())
    exception->Set(v8::Isolate::GetCurrent()->GetCurrentContext(),
                   v8::String::NewFromOneByte(v8::Isolate::GetCurrent(), (const uint8_t*)"stack", v8::NewStringType::kNormal).ToLocalChecked(),
                   stack_trace->GetFrame(0)->GetScriptNameOrSourceURL()).Check();

  return exception;
}

static void throwException(v8::Local<v8::Value> exception) {
  if (v8::Isolate::GetCurrent()->IsExecutionTerminating())
    return;

  v8::Local<v8::Context> context = v8::Isolate::GetCurrent()->GetCurrentContext();
  v8::Local<v8::Value> error_value;
  if (exception->ToObject(context).ToLocal(&error_value))
    v8::Local<v8::Object>::Cast(error_value)->SetPrototype(context, v8::Isolate::GetCurrent()->ThrowError(exception));
}

